-- [F-005] mod-azerothcore-high-elf: High Elf voices from Turtle WoW (optional, replaces the Blood Elf voices)
-- soundentries: 134 inserts; creaturesounddata: 2 inserts; vocaluisounds, creaturedisplayinfo: updates
--
-- Rows ported from Turtle WoW 1.18.1's SoundEntries.dbc, where they reuse the Blood Elf ids with HighElf files
-- (female emote/error lines are re-recorded; some file lists drop lines, e.g. the male Silly ones). Turtle's ids
-- belong to the Blood Elves here, so the rows get a fixed block (200000+) clear of stock (max 18019) and the other
-- modpaks (Open Azeroth goes up to 138066). The BASE vocaluisounds then get repointed from the Blood Elf ids to
-- these; the emotes are rewritten in [F-005]_emotestextsound.sql.
-- Laugh/Cry/Chicken/Kiss are played by the shared Blood Elf model's animation events and stay Blood Elf.
-- Audio files: Turtle's Sound\Character\HighElf\... (.wav), shipped in the client patch.

-- New entries
DELETE FROM `soundentries` WHERE `id` BETWEEN 200000 AND 200133;

-- Combat sounds: own creaturesounddata (copies of Blood Elf 2155/2156), set on the High Elf displays, which
-- take precedence over the shared Blood Elf model's sound data
DELETE FROM `creaturesounddata` WHERE `id` IN (200000, 200001);

UPDATE `creaturedisplayinfo` SET `sound_id` = 200000 WHERE `id` = @HighElfMaleDisplay;
UPDATE `creaturedisplayinfo` SET `sound_id` = 200001 WHERE `id` = @HighElfFemaleDisplay;

-- Repoint the High Elf vocal UI sounds (Blood Elf id -> High Elf id)
DROP TEMPORARY TABLE IF EXISTS `highelf_sound_map`;
CREATE TEMPORARY TABLE `highelf_sound_map` (`blood_elf_id` INT UNSIGNED NOT NULL PRIMARY KEY, `high_elf_id` INT UNSIGNED NOT NULL);

UPDATE `vocaluisounds` v JOIN `highelf_sound_map` m ON m.`blood_elf_id` = v.`normal_sound_id_1`
SET v.`normal_sound_id_1` = m.`high_elf_id` WHERE v.`race_id` = @HighElf;
UPDATE `vocaluisounds` v JOIN `highelf_sound_map` m ON m.`blood_elf_id` = v.`normal_sound_id_2`
SET v.`normal_sound_id_2` = m.`high_elf_id` WHERE v.`race_id` = @HighElf;

DROP TEMPORARY TABLE `highelf_sound_map`;
